<span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;Со свойством hidden&lt;/</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
